<?php require __DIR__.'/../../includes/admin_auth.php';$pdo=db();$s=$pdo->prepare('SELECT * FROM books WHERE id=?');$s->execute([(int)$_GET['id']]);$book=$s->fetch();if(!$book){header('Location:index.php');exit;}$lists=['authors'=>$pdo->query("SELECT id,CONCAT(first_name,' ',last_name) name FROM authors ORDER BY last_name")->fetchAll(),'publishers'=>$pdo->query('SELECT id,name FROM publishers ORDER BY name')->fetchAll(),'categories'=>$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll()];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE books SET title=?,isbn=?,description=?,publication_year=?,pages=?,language=?,author_id=?,publisher_id=?,category_id=? WHERE id=?')->execute([trim($_POST['title']),trim($_POST['isbn']),trim($_POST['description']),(int)$_POST['publication_year'],(int)$_POST['pages'],trim($_POST['language']),(int)$_POST['author_id'],(int)$_POST['publisher_id'],(int)$_POST['category_id'],$book['id']]);log_action(user()['id'],'EDIT_BOOK','book',(int)$book['id'],'Edited book');flash('success','Book updated.');header('Location:index.php');exit;}$pageTitle='Edit book';require __DIR__.'/../../includes/header.php';?><div class="panel"><h1>Edit book</h1><?php require __DIR__.'/_form.php';?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
